	requestedIndices := sortedSliceFromMap(requestedIndicesMap)

	result := make(map[[fieldparams.RootLength]byte][]blocks.VerifiedRODataColumn, len(roots))

	for root := range roots {
		storedIndices := storedIndicesByRoot[root]

